import { Fragment, useEffect, useState } from "react";
import "./App.css";
import Stopwatch from "./Stopwatch";
import React from "react";

function App() {
  // const [time, setTime] = useState(0);

  const [genders, setGenders] = useState({
    m: { display: "Homme", time: 0, running: false },
    f: { display: "Femme", time: 0, running: false },
    nb: { display: "Non-Binaire", time: 0, running: false },
  });
  // useEffect(() => {
  //   let interval;
  //   if (running) {
  //     interval = setInterval(() => {
  //       setTime((prevTime) => prevTime + 10);
  //       (prevTime) => prevTime + 10;
  //     }, 10);
  //   } else if (!running) {
  //     clearInterval(interval);
  //   }
  //   return () => clearInterval(interval);
  // }, [running]);
  return (
    <div className="App">
      {Object.keys(genders).map((gender) => (
        <Fragment>
          <Stopwatch
            display={genders[gender].display}
            key={gender}
            time={genders[gender].time}
            // running={genders[gender].running}
          />
          <button>Start {genders[gender]}</button>
        </Fragment>
      ))}
    </div>
  );
}

export default App;
